"""Render the completed-day research from preserved evidence only."""
from pathlib import Path
import sys, json, csv, html, base64, math, hashlib, zipfile
P = Path(__file__).resolve().parent
ROOT = P.parents[2]
sys.path.insert(0, str(ROOT))
from metro51_report import export_pdf
from interfaces.streamlit_dispatcher.adapter import NAMES
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
plt.rcParams.update({'font.family': 'DejaVu Sans', 'font.size': 10})
R = ROOT/'data/processed/metro52_full_day_20261009'
s = json.loads((P/'summary.json').read_bytes())
a, b = [s['passengers'][x] for x in ['reference', 'balanced']]
e, annual = s['economy']['daily'], s['economy']['annual']
sides = ['without_sr_kr', 'with_sr_kr']
def rows(name, parent=P):
    with (parent/name).open(encoding='utf-8-sig', newline='') as f:
        return list(csv.DictReader(f))
def f(x, n=0): return f'{float(x):,.{n}f}'.replace(',', ' ').replace('.', ',')
def t(x): return f'{int(round(float(x)))//60}:{int(round(float(x)))%60:02}'
def station(sid): return NAMES[int(sid.split('_')[-1])-1]
def savecsv(name, values):
    with (P/name).open('w', encoding='utf-8-sig', newline='') as out:
        w=csv.DictWriter(out, fieldnames=list(values[0])); w.writeheader(); w.writerows(values)
incidents=rows('incident_probes.csv', R/'review')
forecasts=s['forecast']['by_station']
affected=[x for x in s['economy']['per_train'] if abs(x['daily']['saved_km'])>.001]
assert len(affected)==12 and math.isclose(sum(x['daily']['saved_km'] for x in affected), e['saved_km'])
pertrain=[]
for x in s['economy']['per_train']:
    z={'train':x['train_id'],'type':x['train_type']}
    for period in ['daily','annual']:
        z[period+'_saved_km']=x[period]['saved_km']
        for side in sides:
            for key in ['reference_cost_rub','candidate_cost_rub','saving_rub','saving_percent']:
                z[f'{period}_{side}_{key}']=x[period][side][key]
    pertrain.append(z)
savecsv('economy_per_train.csv',pertrain)
savecsv('forecast_by_station.csv',[{'station':station(x['station_id']),**x} for x in forecasts])
savecsv('incident_summary.csv',incidents)
fig, ax=plt.subplots(1,2, figsize=(13,4.8),layout='constrained')
ordered=sorted(forecasts,key=lambda x:x['wape'])
ax[0].barh([station(x['station_id']) for x in ordered],[100*x['wape'] for x in ordered],color=['#d63a46' if x['station_id']=='L1_07' else '#517996' for x in ordered])
ax[0].set(title='Ошибка прогноза по станциям',xlabel='WAPE, %')
ax[1].bar(['3 минуты','8 минут','15 минут'],[float(x['p95_wait_delta_seconds'])/60 for x in incidents],color=['#e8b54c','#d88146','#d63a46'])
ax[1].set(title='Остановка состава: прирост P95 ожидания',ylabel='Минуты относительно исходного графика')
fig.savefig(P/'forecast_incidents.png',dpi=170); plt.close(fig)
fig,ax=plt.subplots(1,2,figsize=(12,4.2),layout='constrained')
ax[0].bar([x['train_id'] for x in affected],[x['daily']['saved_km'] for x in affected],color='#517996');ax[0].tick_params(axis='x',rotation=50)
ax[0].set(title='Сокращение пробега по составам',ylabel='Составо-км за день')
vals=[e[z]['saving_rub']/1000 for z in sides]
ax[1].bar(['Без СР и КР','С СР и КР'],vals,color=['#517996','#d63a46'])
for i,v in enumerate(vals):ax[1].text(i,v+2,f(v,1),ha='center')
ax[1].set(title='Центральная оценка экономии ресурса',ylabel='Тысяч рублей за день',ylim=(0,135))
fig.savefig(P/'economy.png',dpi=170);plt.close(fig)
md=[];ht=[]
def title(text,level=2):md.append('#'*level+' '+text);ht.append(f'<h{level}>{html.escape(text)}</h{level}>')
def para(text):md.append(text);ht.append('<p>'+html.escape(text)+'</p>')
def table(headers, data):
    data=[[str(v) for v in row] for row in data]
    md.append('| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+'\n'.join('| '+' | '.join(row)+' |' for row in data))
    ht.append('<table><thead><tr>'+''.join('<th>'+html.escape(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+html.escape(x)+'</td>' for x in row)+'</tr>' for row in data)+'</tbody></table>')
def page():ht.append('<div class="break"></div>')
def picture(name):
    md.append(f'![Результаты моделирования]({name})')
    ht.append('<img src="data:image/png;base64,'+base64.b64encode((P/name).read_bytes()).decode()+'">')
title('Красная линия: исследование полного суточного прогона',1)
para('Дата исследования: 10.10.2026. Модельный день: 30.09.2026, вход пассажиров 06:00–24:00, завершение наблюдения 01.10 в 02:00. Сравниваются исходный синтетический календарный график FIFO и полный ансамбль с текущим оптимизатором. Медианный оптимизатор и прежний оптимизатор в этом прогоне не участвовали.')
para('Основной результат: расчётный ресурс обслуживания сократился на 2,52–2,56%, а среднее ожидание увеличилось на 2,79 секунды. Все 758 936 пассажиров завершили поездки. Однако цель целиком не выполнена: локальные требования к посадке нарушены в пяти группах в обоих вариантах. Аварийные проверки также не дают основания считать систему готовой к эксплуатации.')
