title('Что доказано этим сравнением')
para('Независимый аудит подтвердил одинаковые пассажирские группы, парк, геометрию, начальные условия и seed=7. Проверены сохранённые траектории, целостность конечных состояний, баланс пассажиров, пробег и ограничения движения. Единственная не пройденная итоговая проверка обоих вариантов: local_boarding_service. Общий статус goal_achieved=false; денежная экономия в кассе и эксплуатационный допуск не установлены.')
para('Пробег сократился на 688,1 км (2,46%), или на 10,12 км в среднем по каждому из 68 составов. Изменения коснулись 12 «Балтийцев»; у остальных 56 составов пробег не изменился. Среднее по всему парку нельзя выдавать за фактическую экономию каждого состава.')
picture('economy.png')
page();title('Экономика: стоимость и экономия вместе',1)
econrows=[]
for label,key,n in [('Исходная стоимость за день, ₽','reference_cost_rub',0),('Стоимость после оптимизации за день, ₽','candidate_cost_rub',0),('Экономия за день, ₽','saving_rub',0),('Экономия, %','saving_percent',2),('Стоимость после оптимизации на состав парка/день, ₽','mean_candidate_cost_per_fixed_train_rub',0),('Экономия на состав парка/день, ₽','mean_saving_per_fixed_train_rub',0),('Стоимость после оптимизации, ₽/составо-км','candidate_rub_per_km',2),('Экономия на сокращённый составо-км, ₽','saving_rub_per_saved_km',2),('Экономия на каждый исходный составо-км, ₽','saving_rub_per_reference_km',2)]:econrows.append([label,*[f(e[z][key],n) for z in sides]])
